// Etat initial neutre : Pro presélectionné (juste milieu), le reste a "Non"
// tant que l'utilisateur n'a pas choisi explicitement "Oui".
const installSelection = {
  plan: 'pro',
  nonplanar: 'no',
  axis45: 'no',
  modeler: 'no',
};

