/* Deux blocs de texte superposes (pre/post), meme crossfade que les deux
   logos : "Aelox Hardware / Chargement en cours" pendant le tracage du
   grand logo, puis "Apex Slicer / Assistant d'installation" une fois le
   petit logo pris le relais. :has() cible .logoRing.drawDone depuis le
   parent .screen commun, evitant d'avoir a dupliquer la logique JS. */
.introTextSwap {
  position: relative;
  width: 100%;
  margin-top: 14px;
}

.introTextPre,
.introTextPost {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  opacity: 0;
  transition: opacity 0.6s ease;
}

.introTextPre .brandTitle,
.introTextPost .brandTitle {
  margin-top: 0;
}

.introTextPre {
  opacity: 1;
}

.screen[data-screen='intro']:has(.logoRing.drawDone) .introTextPre {
  opacity: 0;
}

.screen[data-screen='intro']:has(.logoRing.drawDone) .introTextPost {
  opacity: 1;
  position: static;
}

