.screenLead {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.75);
  line-height: 1.5;
}

/* ---- Ecran d'intro ---- */

/* L'anneau (fond/bordure/lueur) et son pulse ne doivent apparaitre qu'une
   fois le second logo (.logoMark, taille normale) pris le relais - pas
   pendant le tracage du grand logo (.logoDraw) qui doit rester seul, sans
   cercle autour de lui. D'ou les valeurs "vides" par defaut ci-dessous,
   activees seulement par .logoRing.drawDone plus bas. */
.logoRing {
  position: relative;
  width: 96px;
  height: 96px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid transparent;
  box-shadow: none;
  transition: background 0.5s ease, border-color 0.5s ease, box-shadow 0.5s ease;
}

.logoRing.drawDone {
  background: rgba(0, 240, 255, 0.08);
  border-color: rgba(0, 240, 255, 0.35);
  box-shadow: 0 0 40px rgba(0, 240, 255, 0.25);
}

.logoRingPulse {
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  border: 1px solid rgba(0, 240, 255, 0.4);
  opacity: 0;
}

.logoRing.drawDone .logoRingPulse {
  opacity: 1;
  animation: ringPulse 2.2s ease-out infinite;
}

@keyframes ringPulse {
  0% { transform: scale(0.9); opacity: 0.8; }
  100% { transform: scale(1.35); opacity: 0; }
}

/* Logo source (res/logo.svg) en noir quasi pur (#1d1d1b) : filtre CSS pour
   le teinter dans le cyan d'accent (#00f0ff) utilise partout ailleurs
   (brandTitle, boutons primaires...). brightness(0) ramene le trait a du
   noir pur (annule l'anti-aliasing gris), puis invert+sepia+saturate+
   hue-rotate reconstruit la teinte cyan cible ; drop-shadow ajoute la
   meme lueur que le reste des elements cyan de l'UI (logoRing, doneTitle).
   logoBreathe (en plus de l'apparition .animItem ponctuelle) fait "vivre"
   le logo en continu pendant toute la duree de l'ecran intro (~15s, cale
   sur prestart.mp3 - voir PRESTART_DURATION_MS dans renderer.js), au lieu
   de rester fige une fois son animation d'entree terminee.
   Reste cache (opacity:0) tant que .logoRing n'a pas .drawDone : c'est
   .logoDraw (le SVG "trace+remplissage", voir plus bas) qui joue en
   premier, en grand, puis .logoMark prend le relais en fondu. */
.logoMark {
  position: absolute;
  width: 46px;
  height: auto;
  /* drop-shadow sombre (relief) + drop-shadow cyan (lueur d'accent,
     deja presente) : deux drop-shadow s'empilent sans se remplacer. */
  filter: brightness(0) saturate(100%) invert(80%) sepia(45%) saturate(2500%) hue-rotate(140deg) brightness(1.05) drop-shadow(0 3px 8px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 10px rgba(0, 240, 255, 0.5));
  opacity: 0;
  transition: opacity 0.6s ease;
}

.logoRing.drawDone .logoMark {
  position: static;
  opacity: 1;
  animation: logoBreathe 2.2s ease-in-out infinite;
}

/* .logoDraw : le SVG "trace+remplissage" (genere par SVG Artista), affiche
   2.5x plus grand que .logoMark (115px vs 46px) le temps de son animation.
   Une fois le trace termine (classe .active, ~1.7s : dernier stroke a
   0.48s + duree 1s), renderer.js ajoute .shrinking pour le faire revenir
   en fondu vers sa taille normale pendant que .logoMark prend le relais
   (drawDone, voir ci-dessus) - transition fluide entre les deux. */
.logoDraw {
  position: absolute;
  /* Centrage explicite sur le milieu de .logoRing : le viewBox de ce SVG
     (354.3x454.1) n'a pas le meme ratio ni le meme centrage de contenu que
     celui de .logoMark (139.5x123.4, res/logo.svg), donc sans ce
     top/left/transform les deux logos apparaissaient visiblement decales
     l'un par rapport a l'autre au moment de la transition. */
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 115px;
  height: auto;
  overflow: visible;
  /* Remplissage blanc uni (voir #logoDrawSvg.active dans index.html) avec
     ombre portee sombre + legere lueur cyan - effet verre depoli tente
     puis abandonne (backdrop-filter+mask-image ne se rendait pas
     correctement dans ce contexte Electron). */
  filter: drop-shadow(0 4px 10px rgba(0, 0, 0, 0.45)) drop-shadow(0 0 14px rgba(0, 240, 255, 0.4));
  transition: width 0.7s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.6s ease 0.1s;
}

.logoDraw.shrinking {
  width: 46px;
  opacity: 0;
}

.logoRing.drawDone .logoDraw {
  display: none;
}

@keyframes logoBreathe {
  0%, 100% {
    transform: scale(1);
    filter: brightness(0) saturate(100%) invert(80%) sepia(45%) saturate(2500%) hue-rotate(140deg) brightness(1.05) drop-shadow(0 3px 8px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 10px rgba(0, 240, 255, 0.5));
  }
  50% {
    transform: scale(1.06);
    filter: brightness(0) saturate(100%) invert(80%) sepia(45%) saturate(2500%) hue-rotate(140deg) brightness(1.2) drop-shadow(0 3px 8px rgba(0, 0, 0, 0.5)) drop-shadow(0 0 18px rgba(0, 240, 255, 0.75));
  }
}

.brandTitle {
  font-family: 'Orbitron', sans-serif;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.04em;
  /* Espace supplementaire par rapport au logo au-dessus (le gap generique
     de .screen, 18px, les collait trop pres de l'anneau/logo). */
  margin-top: 14px;
}

.brandSubtitle {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.6);
}

