/* L'anneau (fond/bordure/lueur) et son pulse ne doivent apparaitre qu'une
   fois le second logo (.logoMark, taille normale) pris le relais - pas
   pendant le tracage du grand logo (.logoDraw) qui doit rester seul, sans
   cercle autour de lui. D'ou les valeurs "vides" par defaut ci-dessous,
   activees seulement par .logoRing.drawDone plus bas. */
.logoRing {
  position: relative;
  width: 96px;
  height: 96px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid transparent;
  box-shadow: none;
  transition: background 0.5s ease, border-color 0.5s ease, box-shadow 0.5s ease;
}

.logoRing.drawDone {
  background: rgba(0, 240, 255, 0.08);
  border-color: rgba(0, 240, 255, 0.35);
  box-shadow: 0 0 40px rgba(0, 240, 255, 0.25);
}

.logoRingPulse {
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  border: 1px solid rgba(0, 240, 255, 0.4);
  opacity: 0;
}

.logoRing.drawDone .logoRingPulse {
  opacity: 1;
  animation: ringPulse 2.2s ease-out infinite;
}

@keyframes ringPulse {
  0% { transform: scale(0.9); opacity: 0.8; }
  100% { transform: scale(1.35); opacity: 0; }
}

