content.content:
85	// cible recoit .animItem + un delai (--stagger) proportionnel a sa
86	// position, pour une sequence lente et bien separee (voir styles.css,
87	// section "Animation d'entree par element"). STAGGER_STEP_MS plus large
88	// qu'au premier jet pour laisser chaque etape se terminer avant la
89	// suivante plutot que de les faire se chevaucher.
90	const STAGGER_STEP_MS = 130;
91	
92	function primeScreenAnimations(screen) {
93	  const items = screen.querySelectorAll(
94	    // .brandTitle/.brandSubtitle retires : ils sont geres par le crossfade
