/* Anneau autour du logo Apex (res/logo.svg), affiche directement - le
   logo Aelox anime (trace SVG) qui s'affichait avant lui a ete retire,
   mais la pulsation du cercle est conservee via ::after (remplace la
   div .logoRingPulse retiree du DOM avec le reste du logo Aelox). */
.logoRing {
  position: relative;
  width: 96px;
  height: 96px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 240, 255, 0.08);
  border: 1px solid rgba(0, 240, 255, 0.35);
  box-shadow: 0 0 40px rgba(0, 240, 255, 0.25);
}

.logoRing::after {
  content: '';
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  border: 1px solid rgba(0, 240, 255, 0.4);
  animation: ringPulse 2.2s ease-out infinite;
}

@keyframes ringPulse {
  0% { transform: scale(0.9); opacity: 0.8; }
  100% { transform: scale(1.35); opacity: 0; }
}

